import json,sys
T='/root/.claude/projects/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d.jsonl'
a,b=int(sys.argv[1]),int(sys.argv[2]); tl=int(sys.argv[3]) if len(sys.argv)>3 else 300
res=int(sys.argv[4]) if len(sys.argv)>4 else 0
for n,line in enumerate(open(T,errors='replace'),1):
    if n<a: continue
    if n>b: break
    try: r=json.loads(line)
    except: continue
    t=r.get('type')
    if t not in('user','assistant'): continue
    c=r['message']['content']
    ts=r.get('timestamp')
