        print(f'--- L{n} {ts} {t} [str]'); print(c[:2000 if t=="user" else 100000]); continue
    for blk in c:
        bt=blk.get('type')
        if bt=='text': print(f'--- L{n} {ts} {t} text'); print(blk['text'])
        elif bt=='tool_use':
            inp=json.dumps(blk['input'],ensure_ascii=False)
            print(f'--- L{n} {ts} tool_use {blk["name"]}: {inp[:tl]}')
        elif bt=='tool_result' and res:
            cc=blk.get('content'); 
            if isinstance(cc,list): cc=' '.join(x.get('text','') for x in cc if isinstance(x,dict))
            print(f'--- L{n} {ts} tool_result: {str(cc)[:res]}')
